<script setup lang="ts">
import { computed, ref } from 'vue'; import type { Entity } from '@zhijiao/shared'; import { entities, directory } from '../state'; import { titleOf, label, dateLabel } from '../format'; import Drawer from './Drawer.vue'; import Icon from './Icon.vue'; import InteractionAnalysis from './InteractionAnalysis.vue';
const props = defineProps<{ record: Entity }>(); const emit = defineEmits<{ close: []; edit: [record: Entity]; history: [record: Entity]; remove: [record: Entity]; open: [record: Entity] }>();
const analysisOpen = ref(false);
const fieldLabels: Record<string, string> = { fullName:'正式姓名',aliases:'别名',summary:'摘要',metContext:'相识背景',metOn:'相识日期',birthday:'生日',notes:'备注',status:'状态',type:'类型',value:'联系内容',preferred:'优先使用',basis:'来源性质',category:'类别',sourceNote:'来源说明',sourceInteractionId:'来源交往',learnedOn:'获知日期',validFrom:'有效期起',validTo:'有效期止',supersedesFactId:'替代事实',kindOfInteraction:'交往类型',occurredOn:'发生日期',occurredAt:'精确时间',timezone:'时区',channel:'渠道',location:'地点',content:'内容',context:'语境',evidence:'支持理由',counterEvidence:'反例或其他解释',certainty:'主观把握',recordedOn:'记录日期',supersedesId:'修正的旧印象',responsibility:'责任',details:'细节',dueDate:'期限日期',dueAt:'精确期限',completedAt:'完成时间',label:'用途说明' };
const fields = computed(() => Object.entries(props.record).filter(([key, value]) => key in fieldLabels && value !== undefined && value !== '').map(([key, value]) => ({ key, title: fieldLabels[key], value: key.endsWith('Id') ? titleOf(entities.value.find(record => record.id === value) ?? props.record) : Array.isArray(value) ? value.join('、') : typeof value === 'boolean' ? value ? '是' : '否' : ['status','type','basis','responsibility'].includes(key) ? label(String(value)) : /On$|Date$|At$/.test(key) ? dateLabel(String(value)) : String(value) })));
const participantIds = computed(() => 'participantIds' in props.record ? props.record.participantIds : 'personIds' in props.record ? props.record.personIds : 'personId' in props.record ? [props.record.personId] : []);
const links = computed(() => entities.value.filter(record => record.kind === 'reflectionLink' && (props.record.kind === 'reflection' ? record.reflectionId === props.record.id : props.record.kind === 'interaction' ? record.interactionId === props.record.id : false)).map(record => { if (record.kind !== 'reflectionLink') throw Error(); const related = entities.value.find(entity => entity.id === (props.record.kind === 'reflection' ? record.interactionId : record.reflectionId)); return { record, related }; }));
</script>
<template>
  <Drawer :title="titleOf(record)" :subtitle="label(record.kind)" @close="emit('close')">
    <div v-if="participantIds.length" class="record-participants"><span v-for="id in participantIds" :key="id" class="chip">{{ directory.find(person => person.personId === id)?.displayName || '已删除或尚未同步人物' }}</span></div>
    <p v-else-if="record.kind === 'interaction'" class="muted">未关联人物，可在编辑时补关联。</p>
    <button v-if="record.kind === 'interaction'" class="button secondary record-analysis-button" @click="analysisOpen = true"><Icon name="people" :size="17" />分析人物与事项</button>
    <dl class="definition-list record-definition"><template v-for="field in fields" :key="field.key"><dt>{{ field.title }}</dt><dd class="preserve">{{ field.value }}</dd></template></dl>
    <section v-if="links.length" class="form-section"><h3>{{ record.kind === 'reflection' ? '事件依据' : '相关感受与印象' }}</h3><button v-for="item in links" :key="item.record.id" class="link-card" :disabled="!item.related" @click="item.related && emit('open', item.related)"><span class="badge">{{ label(item.record.relationType) }}</span><strong>{{ item.related ? titleOf(item.related) : '已删除或尚未同步的记录' }}</strong><p v-if="item.record.explanation">{{ item.record.explanation }}</p></button></section>
    <p class="muted form-note">更新于 {{ dateLabel(record.updatedAt) }}</p><button class="text-button danger" @click="emit('remove', record)">删除这条记录</button>
    <template #footer><button class="button secondary" @click="emit('history', record)"><Icon name="history" :size="17" />查看历史</button><button class="button primary" @click="emit('edit', record)">编辑</button></template>
  </Drawer>
  <InteractionAnalysis v-if="analysisOpen && record.kind === 'interaction'" :record="record" @close="analysisOpen = false" />
</template>
